insert into tasks (domain, week_number, title, description, difficulty, requirements, resources, checklist, order_index) values
('frontend', 1, 'Build a Responsive Landing Page', 'Build a responsive landing page from a spec using only HTML/CSS/JS — no frameworks.', 'easy', '["Must work correctly at 320px, 768px, and 1440px widths", "Include a hero section, a features section (3+ items), and a footer", "Nav must collapse into a hamburger menu below 768px", "No CSS frameworks (Bootstrap/Tailwind) \u2014 write your own CSS"]'::jsonb, '["Any free Figma/Dribbble landing page design as your visual reference", "MDN CSS Flexbox/Grid docs"]'::jsonb, '["Loads with no console errors", "Layout doesn''t break at any of the 3 required widths", "Hamburger menu actually opens/closes on mobile", "Semantic HTML tags used (nav, header, section, footer)"]'::jsonb, 1),
('frontend', 1, 'Componentize a Static Page', 'Convert a static page into React components using props and state.', 'easy', '["Break the page into at least 4 reusable components", "At least one component must accept props", "At least one component must use useState for interactive behavior (e.g. a toggle or counter)", "No single component file over ~150 lines \u2014 split further if it is"]'::jsonb, '["Reuse the landing page from Week 1 Task 1 as the source page", "React docs: Passing Props, useState"]'::jsonb, '["Components are genuinely reusable, not just copy-pasted markup", "State updates correctly re-render the UI", "No prop-drilling more than 2 levels deep without justification", "Code runs with no console warnings"]'::jsonb, 2),
('frontend', 2, 'Form with Validation', 'Build a form with client-side validation and a mock API integration.', 'medium', '["Fields: name, email, password, confirm password \u2014 each with real validation rules", "Show inline error messages, not just a generic alert", "Disable submit until the form is valid", "On submit, POST to a mock endpoint (e.g. jsonplaceholder) and show a success/error state"]'::jsonb, '["jsonplaceholder.typicode.com for the mock POST endpoint", "MDN Constraint Validation API"]'::jsonb, '["Every field has a specific, correct validation rule (not just ''required'')", "Errors clear when the user fixes the input", "Loading state shown while the mock request is in flight", "Works with keyboard navigation, not just mouse"]'::jsonb, 1),
('frontend', 2, 'API-Driven Dashboard UI', 'Build a dashboard UI consuming a public API — charts, filters, pagination.', 'medium', '["Fetch real data from a public API (not hardcoded)", "Include at least one chart (bar, line, or pie)", "Include at least one working filter and pagination or infinite scroll", "Handle loading and error states explicitly, don''t just leave it blank"]'::jsonb, '["A public API such as OpenWeather, TMDB, or REST Countries", "Recharts or Chart.js for the chart"]'::jsonb, '["Data genuinely comes from the live API, not mocked", "Filter actually changes the displayed data", "Pagination/infinite scroll works without duplicating or skipping items", "Loading and empty/error states are visibly different from each other"]'::jsonb, 2),
('frontend', 3, 'Multi-Page React App', 'Build a multi-page React app with routing, global state, and a reusable component library.', 'hard', '["At least 3 distinct routes using React Router", "Global state shared across at least 2 pages (Context or a state library)", "A component library folder reused across at least 3 places in the app", "Proper 404 handling for unknown routes"]'::jsonb, '["React Router docs", "Any state library: Context API, Zustand, Redux"]'::jsonb, '["Routing works on direct URL entry, not just in-app navigation", "Global state updates are reflected everywhere it''s used", "No component duplicated instead of reused", "404 page exists and is reachable"]'::jsonb, 1),
('frontend', 3, 'Performance & Accessibility Pass', 'Run a Lighthouse audit on an existing app and fix performance/accessibility issues.', 'hard', '["Run Lighthouse before and after \u2014 submit both scores", "Fix at least 3 real accessibility issues (not just alt text)", "Fix at least 2 real performance issues (image sizing, unused JS, etc.)", "Final Accessibility score must be 90+"]'::jsonb, '["Chrome DevTools Lighthouse tab", "web.dev/measure"]'::jsonb, '["Before/after Lighthouse scores are both included in the submission", "Accessibility score is 90 or above after fixes", "Fixes are real code changes, not score gaming", "App still functions correctly after changes"]'::jsonb, 2),
('frontend', 4, 'Capstone: Full Product UI', 'Build and deploy a polished, fully responsive product UI (auth screens, dashboard, settings) consuming a real or mock API.', 'hard', '["Auth screens (login/signup), a main dashboard, and a settings page \u2014 3+ screens minimum", "Fully responsive from mobile to desktop", "Consumes a real or realistic mock API for at least the dashboard data", "Deployed and publicly reachable via a live URL"]'::jsonb, '["Vercel or Netlify for deployment", "Any auth-less mock API or Supabase for data"]'::jsonb, '["Live URL works and loads without errors", "All 3+ screens are reachable and functional", "Responsive across mobile/tablet/desktop", "Submission includes the live URL, not just the repo"]'::jsonb, 1),
('backend', 1, 'REST API with CRUD', 'Build a REST API (CRUD) with Node/Express and a database.', 'easy', '["At least one resource with full Create/Read/Update/Delete endpoints", "Data persists in a real database (not in-memory array)", "Proper HTTP status codes (200/201/400/404/500)", "Basic input validation on create/update"]'::jsonb, '["Express.js docs", "Any DB: Supabase/Postgres, MongoDB, SQLite"]'::jsonb, '["All 4 CRUD operations work and persist correctly", "Status codes are correct, not always 200", "Invalid input is rejected with a 400, not a crash", "Repo includes instructions to run it locally"]'::jsonb, 1),
('backend', 1, 'Auth & Roles', 'Add authentication (JWT) and role-based access control to an API.', 'easy', '["Signup/login issuing a JWT", "At least one protected route requiring a valid token", "At least 2 roles (e.g. user/admin) with different access", "Passwords hashed, never stored in plain text"]'::jsonb, '["jsonwebtoken npm package", "bcrypt for password hashing"]'::jsonb, '["Protected routes reject requests with no/invalid token", "Role check actually blocks the wrong role, not just cosmetic", "Passwords are hashed in the database", "Token expiry is implemented"]'::jsonb, 2),
('backend', 2, 'File Upload Service', 'Build a file upload service with validation and storage.', 'medium', '["Accept file uploads via a real endpoint (not base64 in JSON)", "Validate file type and size, reject invalid ones", "Store files somewhere durable (cloud storage or a persistent volume)", "Return a usable URL/reference after upload"]'::jsonb, '["Multer for handling multipart uploads", "Supabase Storage or S3-compatible storage"]'::jsonb, '["Invalid file types/oversized files are rejected with a clear error", "Valid uploads are retrievable afterward via the returned reference", "No files silently lost or corrupted", "Upload endpoint doesn''t crash on malformed requests"]'::jsonb, 1),
('backend', 2, 'Rate Limiting & Logging', 'Design and implement rate limiting and structured logging middleware.', 'medium', '["Rate limit at least one endpoint (e.g. 10 requests/minute per IP)", "Return a proper 429 status when the limit is hit", "Structured (JSON) request logging with method, path, status, duration", "Logging middleware applied globally, not per-route"]'::jsonb, '["express-rate-limit npm package", "morgan or a custom logging middleware"]'::jsonb, '["Exceeding the limit actually returns 429, verified by testing", "Logs are structured/parseable, not just console.log strings", "Rate limit resets correctly after the window", "Logging doesn''t leak sensitive data like passwords"]'::jsonb, 2),
('backend', 3, 'Search & Pagination at Scale', 'Build a paginated, filterable, searchable API on a large dataset.', 'hard', '["Dataset with 1000+ realistic rows", "Pagination via query params (page/limit or cursor)", "At least one filter and one search-by-text parameter", "Indexed appropriately so queries stay fast as data grows"]'::jsonb, '["Any public dataset (e.g. from Kaggle) seeded into your DB", "Database indexing docs for your chosen DB"]'::jsonb, '["Pagination doesn''t return duplicate/skipped rows across pages", "Search returns relevant results, not just exact matches", "Query performance is reasonable on the full dataset", "Invalid page/limit values are handled gracefully"]'::jsonb, 1),
('backend', 3, 'Background Jobs', 'Add a background job/queue for a long-running task.', 'hard', '["A task that would block a request if run synchronously (e.g. sending 100 emails)", "Moved to a background queue/worker instead of blocking the API response", "API responds immediately while the job processes separately", "Job failures are logged, not silently swallowed"]'::jsonb, '["BullMQ or a simple queue with Redis", "node-cron if a scheduled variant fits better"]'::jsonb, '["API response time isn''t blocked by the long task", "Job actually completes correctly in the background", "Failed jobs are visible/logged, not lost silently", "Solution doesn''t just fake async with setTimeout"]'::jsonb, 2),
('backend', 4, 'Capstone: Production-Style API', 'Design and build a production-style API service (auth, roles, rate limiting, logging, tests, docs) ready to plug into a frontend.', 'hard', '["Combines auth+roles, rate limiting, structured logging from earlier weeks into one service", "At least 5 endpoints across 2+ resources", "Automated tests covering the core endpoints", "README documenting how to run it and every endpoint''s contract"]'::jsonb, '["Jest or a similar test runner", "Postman/Insomnia to document and verify endpoints"]'::jsonb, '["Tests actually run and pass", "README is accurate \u2014 following it works on a clean machine", "Auth, roles, rate limiting, and logging are all present and working together", "API is deployed and reachable, not just local"]'::jsonb, 1),
('fullstack', 1, 'Full CRUD App', 'Build a full CRUD app (auth + DB + frontend) — e.g. a mini task tracker.', 'easy', '["Frontend + backend + real database, all connected", "User can create, view, edit, delete their own records", "Basic auth (even simple email/password) gating access", "Data persists across page reloads"]'::jsonb, '["Supabase for auth+DB in one place if you want to move faster"]'::jsonb, '["All CRUD operations work end-to-end through the actual UI", "Data survives a page refresh", "Only the logged-in user''s own data is shown/editable", "No obvious crashes on empty states (0 records)"]'::jsonb, 1),
('fullstack', 1, 'Role-Based Views', 'Add role-based views (admin vs regular user) to the app.', 'easy', '["At least 2 roles with genuinely different UI/permissions", "Admin can see/manage data regular users can''t", "Role check enforced on the backend, not just hidden in the frontend", "Clear UI indication of which role is currently logged in"]'::jsonb, '["Reuse the CRUD app from Task 1 as the base"]'::jsonb, '["Regular users truly cannot access admin-only data (test by calling the API directly, not just clicking UI)", "Role is stored server-side, not just in frontend state", "UI clearly differs between roles", "No broken states when switching users"]'::jsonb, 2),
('fullstack', 2, 'Real-Time Features', 'Add real-time features (websockets or Supabase Realtime).', 'medium', '["At least one feature updates live across clients without a manual refresh", "Works with 2+ browser tabs/users simultaneously", "Handles connection drops without crashing the UI", "No excessive re-renders/performance issues from the real-time updates"]'::jsonb, '["Supabase Realtime or Socket.io"]'::jsonb, '["Opening the app in two tabs shows changes propagate live", "No memory leaks from unclosed subscriptions", "UI doesn''t flicker or duplicate data on updates", "Reconnects gracefully after a dropped connection"]'::jsonb, 1),
('fullstack', 2, 'CI/CD Deploy', 'Deploy a full-stack app with CI/CD to Vercel and a hosted database.', 'medium', '["App auto-deploys on push to main", "Environment variables properly configured for production, not hardcoded", "Hosted database (not local/sqlite) used in production", "Build fails visibly if tests/lint fail, not silently"]'::jsonb, '["Vercel''s Git integration", "GitHub Actions if you want explicit CI steps"]'::jsonb, '["A push to main triggers a real deploy that works", "Secrets aren''t committed to the repo", "Production app actually connects to the hosted DB successfully", "Failed builds are visible, not deployed silently broken"]'::jsonb, 2),
('fullstack', 3, 'Payments/Uploads Integration', 'Add payment or file-upload integration to an existing full-stack app.', 'hard', '["Real integration with a payment (test mode) or file storage provider", "Handles the failure case (declined payment / failed upload) gracefully", "Confirmation state is persisted, not just shown once and forgotten", "No sensitive keys exposed to the frontend"]'::jsonb, '["Stripe test mode, or Supabase Storage for uploads"]'::jsonb, '["Success and failure paths both work and are tested", "Secret keys are server-side only, verified by checking frontend bundle", "State is correctly persisted after the action completes", "UI gives clear feedback during processing, not just a frozen button"]'::jsonb, 1),
('fullstack', 3, 'Admin Panel & Analytics', 'Build an admin panel with protected routes and basic analytics.', 'hard', '["Admin-only routes, inaccessible to regular users even via direct URL", "At least 2 real metrics displayed (counts, trends, etc.) from real data", "A way to manage (view/edit/delete) core app data from the panel", "Reasonably usable UI, not just a raw data dump"]'::jsonb, '["Recharts for simple analytics charts"]'::jsonb, '["Non-admin users are blocked at the backend level, not just hidden in UI", "Metrics reflect real data, not placeholders", "Admin actions (edit/delete) actually work and persist", "Panel is navigable without needing to read the code"]'::jsonb, 2),
('fullstack', 4, 'Capstone: Complete Product', 'Build a complete full-stack product end-to-end (auth, roles, real-time or notifications, admin panel, deployed) — essentially a mini version of this platform.', 'hard', '["Combines auth+roles, real-time or notifications, and an admin panel into one deployed product", "At least 3 user-facing pages plus the admin panel", "Deployed with CI/CD, publicly reachable", "README explaining the product, architecture, and how to run it"]'::jsonb, '["Everything built in Weeks 1-3 as building blocks"]'::jsonb, '["Live URL works end-to-end for both a regular user and an admin flow", "README accurately describes the architecture", "No critical console errors on core flows", "Deployment is automatic on push, not manual"]'::jsonb, 1),
('genai', 1, 'Prompt-Based Text Generator', 'Build a prompt-based text generator using an LLM API with reusable prompt templates.', 'easy', '["Calls a real LLM API (not hardcoded responses)", "At least 2 reusable prompt templates with variable substitution", "Basic UI or CLI to input variables and see output", "Handles API errors (rate limit, timeout) without crashing"]'::jsonb, '["Anthropic or OpenAI API docs"]'::jsonb, '["Output genuinely comes from the API for different inputs, not cached/faked", "Templates are reused, not copy-pasted per call", "Errors are caught and shown to the user, not a raw stack trace", "API key is not hardcoded in committed code"]'::jsonb, 1),
('genai', 1, 'Structured Output Extractor', 'Build an extractor that turns messy text into clean JSON using an LLM.', 'easy', '["Input: unstructured/messy text (e.g. a pasted email or note)", "Output: valid, parseable JSON matching a defined schema", "Handles at least 3 different messy input examples correctly", "Validates the LLM''s output actually matches the expected schema before returning it"]'::jsonb, '["JSON mode / structured output features of your chosen LLM API"]'::jsonb, '["Output is valid JSON every time, tested across multiple inputs", "Schema is consistently followed, not loosely ''close enough''", "Malformed LLM output is caught and handled, not passed through broken", "Code includes the 3+ test examples and results"]'::jsonb, 2),
('genai', 2, 'RAG Mini Chatbot', 'Build a RAG (retrieval-augmented generation) mini chatbot over a small document set.', 'medium', '["A small set of real documents (5-20) as the knowledge source", "Documents are chunked and embedded, not stuffed whole into the prompt", "Chatbot answers questions using retrieved chunks, with some indication of source", "Correctly says it doesn''t know when the answer isn''t in the documents"]'::jsonb, '["A vector store: Supabase pgvector, Pinecone, or even an in-memory array for this scale"]'::jsonb, '["Answers are grounded in the actual documents, verified by spot-checking", "Chunking strategy is reasonable, not one giant chunk", "Out-of-scope questions are handled honestly, not hallucinated", "Retrieval step is demonstrably used, not bypassed"]'::jsonb, 1),
('genai', 2, 'Tool-Calling Agent', 'Build an AI agent that can call 1-2 tools (e.g. search and summarize).', 'medium', '["At least one real tool the model can call (search, calculator, API lookup)", "Model correctly decides when to use the tool vs. answer directly", "Tool results are fed back into the model''s final answer", "Handles the case where a tool call fails"]'::jsonb, '["Function calling / tool use features of your chosen LLM API"]'::jsonb, '["Tool is actually invoked for relevant queries, verified by logging", "Model doesn''t call the tool for questions that don''t need it", "Final answer correctly incorporates the tool''s result", "Tool failure doesn''t crash the whole interaction"]'::jsonb, 2),
('genai', 3, 'Multi-Turn Memory', 'Add memory/context handling to a chatbot across a multi-turn conversation.', 'hard', '["Chatbot correctly references earlier turns in a conversation (e.g. ''what did I just ask?'')", "Conversation history is managed within context limits, not just infinitely appended", "Memory persists across a session, not reset per message", "Demonstrates at least one multi-turn conversation of 5+ exchanges"]'::jsonb, '["Your LLM provider''s context window docs"]'::jsonb, '["Bot correctly recalls earlier context in the demo conversation", "History doesn''t silently overflow the context window", "No duplicate/contradictory context sent to the model", "Session boundaries are handled sensibly"]'::jsonb, 1),
('genai', 3, 'Prompt Evaluation', 'Evaluate and improve prompt quality systematically with a test set and scoring.', 'hard', '["A test set of at least 10 representative inputs with expected outcomes", "A scoring method (rubric or automated check) applied consistently", "At least 2 prompt iterations compared against the same test set", "Written summary of what changed and why it improved results"]'::jsonb, '["A simple spreadsheet or script to track scores across iterations"]'::jsonb, '["Test set is genuinely representative, not cherry-picked easy cases", "Scoring is applied the same way across iterations, not subjective per-run", "Improvement between iterations is demonstrated with actual numbers", "Summary clearly explains the reasoning, not just ''it got better''"]'::jsonb, 2),
('genai', 4, 'Capstone: AI-Powered Feature', 'Build a complete AI-powered feature end-to-end (e.g. resume screener, support bot, content generator) with a real UI and error handling.', 'hard', '["A real, usable feature with a UI \u2014 not just an API call in a terminal", "Combines at least 2 techniques from earlier weeks (RAG, tools, structured output, etc.)", "Handles errors and edge cases (empty input, API failure, unexpected output) gracefully", "Deployed and reachable via a live URL"]'::jsonb, '["Everything from Weeks 1-3 as building blocks"]'::jsonb, '["Live URL works for a real end-to-end use case", "At least 2 prior techniques are genuinely combined, not just one", "Error/edge cases don''t break the UI", "Feature is coherent enough that a stranger could use it without explanation"]'::jsonb, 1),
('ml', 1, 'EDA & Data Cleaning', 'EDA and data cleaning on a real messy dataset.', 'easy', '["Use a real dataset with actual missing values/outliers (not pre-cleaned)", "Identify and handle missing values with a justified strategy", "Identify and address at least one outlier or inconsistency", "Produce at least 3 meaningful visualizations of the data"]'::jsonb, '["Kaggle for a messy real-world dataset", "pandas, matplotlib/seaborn"]'::jsonb, '["Missing value strategy is explained, not just dropped blindly", "Visualizations reveal something real about the data", "Cleaning steps are reproducible (in a notebook/script, not manual edits)", "Final cleaned dataset is usable for modeling"]'::jsonb, 1),
('ml', 1, 'ML Toolkit Setup', 'Set up your ML toolkit and explore your first dataset.', 'easy', '["Working local or notebook environment (Jupyter/Colab) with core libraries installed", "Load and summarize a real dataset (shape, types, basic stats)", "At least one plot showing the target variable''s distribution", "Written notes on initial observations about the data"]'::jsonb, '["Google Colab if local setup is a blocker", "A beginner-friendly dataset like Iris, Titanic, or a Kaggle starter set"]'::jsonb, '["Environment actually runs without errors", "Summary stats are correct and meaningful", "At least one distribution plot is included", "Notes show genuine engagement with the data, not just boilerplate"]'::jsonb, 2),
('ml', 2, 'Classification Model', 'Build and evaluate a classification model.', 'medium', '["Train a classification model on a real dataset with a proper train/test split", "Report accuracy AND at least one other metric (precision/recall/F1)", "Include a confusion matrix", "Briefly explain what the model got wrong and why"]'::jsonb, '["scikit-learn", "Titanic dataset or similar for a clean classification target"]'::jsonb, '["Train/test split is done correctly, no data leakage", "Metrics beyond accuracy are reported and interpreted", "Confusion matrix is included and explained", "Analysis of errors shows real understanding, not just numbers"]'::jsonb, 1),
('ml', 2, 'Regression Model', 'Build a regression model and explain feature importance.', 'medium', '["Train a regression model on a real dataset with numeric target", "Report at least 2 regression metrics (e.g. RMSE, R\u00b2)", "Identify and explain the top 3 most important features", "Visualize predicted vs actual values"]'::jsonb, '["scikit-learn", "House prices or similar dataset for a clean regression target"]'::jsonb, '["Metrics are correctly computed and interpreted", "Feature importance explanation makes logical sense, not just listed", "Predicted vs actual plot is included", "Model isn''t wildly overfit (train and test metrics are reasonably close)"]'::jsonb, 2),
('ml', 3, 'Model Comparison', 'Try 2-3 model types on the same problem and compare metrics.', 'hard', '["Same dataset and same train/test split used across all models for fair comparison", "At least 3 different model types tried (e.g. logistic regression, random forest, gradient boosting)", "Comparison table of metrics across all models", "Recommendation of which model to use, with reasoning"]'::jsonb, '["scikit-learn''s various classifiers/regressors"]'::jsonb, '["Comparison is fair \u2014 same data split used throughout", "At least 3 genuinely different model types, not variations of one", "Recommendation is justified with the actual metrics, not just gut feeling", "Code is reproducible end-to-end"]'::jsonb, 1),
('ml', 3, 'Imbalanced Data & Tuning', 'Handle imbalanced data and tune hyperparameters on a real dataset.', 'hard', '["Dataset with real class imbalance (e.g. fraud detection, rare event prediction)", "Apply at least one imbalance-handling technique (resampling, class weights, etc.)", "Perform hyperparameter tuning (grid/random search) and report the improvement", "Compare before/after metrics clearly"]'::jsonb, '["imbalanced-learn for resampling techniques", "scikit-learn''s GridSearchCV/RandomizedSearchCV"]'::jsonb, '["Imbalance technique demonstrably improves relevant metrics (not just accuracy, which is misleading here)", "Tuning process and results are documented", "Before/after comparison is clear and honest", "No data leakage introduced by the resampling step"]'::jsonb, 2),
('ml', 4, 'Capstone: Deployed Model', 'Build, evaluate, and deploy a model behind a simple inference API, with a short report justifying model choice.', 'hard', '["Final trained model with documented evaluation metrics", "Model served behind a real API endpoint that accepts input and returns a prediction", "Short written report: problem, approach, model choice, results, limitations", "API is reachable and testable, not just described"]'::jsonb, '["Flask/FastAPI for the inference endpoint, or a serverless function"]'::jsonb, '["API actually returns correct predictions for test inputs", "Report clearly justifies the final model choice with evidence", "Limitations are honestly discussed, not omitted", "Endpoint is deployed and reachable, not just local"]'::jsonb, 1),
('automation', 1, 'Repetitive Task Script', 'Write a script that automates a repetitive task (file processing, report generation).', 'easy', '["Solves a genuine repetitive task (renaming files, merging CSVs, generating a report, etc.)", "Runs via a single command, no manual steps in between", "Handles at least one edge case (empty input, missing file) without crashing", "Includes example input/output to demonstrate it working"]'::jsonb, '["Python or Node.js, whichever you''re more comfortable with"]'::jsonb, '["Script runs successfully on the provided example input", "Edge case handling is demonstrated, not just assumed", "No hardcoded file paths that only work on the developer''s machine", "Output is correct and verifiable"]'::jsonb, 1),
('automation', 1, 'Scheduled Job', 'Build a scheduled job (cron) that runs a task automatically.', 'easy', '["A real task that benefits from running on a schedule (cleanup, daily report, etc.)", "Actually scheduled (cron, node-cron, or a hosted scheduler), not manually triggered", "Logs when it runs and what it did", "Handles the case where the task fails without crashing the scheduler"]'::jsonb, '["node-cron, or your OS''s native cron", "Vercel Cron Jobs if deploying serverless"]'::jsonb, '["Scheduling is real and demonstrated (screenshot/logs of multiple runs)", "Logs clearly show success/failure per run", "A failure doesn''t take down future scheduled runs", "Task does something meaningfully useful, not a trivial print statement"]'::jsonb, 2),
('automation', 2, 'Web Scraper + DB', 'Build a web scraper that stores results in a database.', 'medium', '["Scrapes real data from a real (permission-appropriate) website", "Stores results in a real database, not just printed to console", "Handles missing/changed page elements without crashing entirely", "Avoids re-scraping/duplicating data already stored"]'::jsonb, '["BeautifulSoup or Playwright/Puppeteer for scraping", "Supabase or SQLite for storage"]'::jsonb, '["Scraper actually pulls real, current data on a test run", "Data is correctly stored and queryable in the DB", "Duplicate entries are avoided on repeated runs", "Scraper doesn''t crash entirely if one page element is missing"]'::jsonb, 1),
('automation', 2, 'Notification Bot', 'Build a notification bot (Slack/WhatsApp/email) for an event trigger.', 'medium', '["A real trigger condition (new data, threshold crossed, error occurred, etc.)", "Sends an actual notification via a real channel, not just logged", "Notification includes useful context, not just ''something happened''", "Doesn''t spam \u2014 avoids duplicate notifications for the same event"]'::jsonb, '["Slack webhooks, Resend/SendGrid for email, or a WhatsApp API"]'::jsonb, '["Notification is demonstrated actually arriving in the real channel", "Message content is genuinely useful/readable, not raw JSON", "Duplicate-prevention logic is present and tested", "Trigger condition is correctly detected, not overly broad"]'::jsonb, 2),
('automation', 3, 'Data Pipeline', 'Build a data pipeline that pulls from an API, transforms it, and stores it.', 'hard', '["Pulls real data from a real API on a schedule or trigger", "Transforms the data meaningfully (cleaning, joining, aggregating) before storing", "Stores the transformed result in a queryable database", "Pipeline can be re-run safely without corrupting existing data"]'::jsonb, '["Any public API with enough data to make transformation meaningful", "Supabase/Postgres for storage"]'::jsonb, '["Pipeline runs end-to-end successfully on a real trigger", "Transformation step demonstrably changes/improves the raw data", "Re-running the pipeline doesn''t create duplicates or corrupt data", "Failures at any pipeline stage are logged clearly"]'::jsonb, 1),
('automation', 3, 'Error Handling & Retries', 'Add error handling, retries, and logging to an automation script.', 'hard', '["Take an existing automation (yours or a provided one) and add real resilience", "Retries failed operations with backoff, not an infinite tight loop", "Logs each failure and retry attempt with enough detail to debug", "Gives up gracefully after a max retry count instead of hanging forever"]'::jsonb, '["Reuse a script from an earlier week as the base"]'::jsonb, '["Retry logic is demonstrated working against a simulated failure", "Backoff increases between retries, not constant/instant retrying", "Logs are detailed enough to diagnose what failed and why", "Script terminates gracefully after max retries, doesn''t hang"]'::jsonb, 2),
('automation', 4, 'Capstone: Full Automation Pipeline', 'Build a full automation pipeline (trigger → process → notify → store) with monitoring and failure alerts.', 'hard', '["Combines a trigger, a processing step, a notification, and storage into one pipeline", "Includes monitoring \u2014 some way to see if the pipeline is healthy", "Sends a real alert if the pipeline fails, not just a silent log entry", "Documented well enough that someone else could operate it"]'::jsonb, '["Everything built in Weeks 1-3 as building blocks"]'::jsonb, '["Full pipeline runs end-to-end successfully on a real trigger", "A simulated failure correctly triggers a real alert", "Monitoring genuinely reflects pipeline health, not just ''it''s running''", "Documentation is clear enough to hand off to someone else"]'::jsonb, 1),
('uiux', 1, 'Wireframe a Product Flow', 'Wireframe a product flow from a brief (low-fidelity).', 'easy', '["Choose or receive a realistic product brief (e.g. ''onboarding flow for a fitness app'')", "Produce low-fidelity wireframes for at least 4 connected screens", "Show the flow/connections between screens (arrows or a flow diagram)", "Annotate key decisions \u2014 why this layout, why this order"]'::jsonb, '["Figma, Balsamiq, or even pen and paper photographed cleanly"]'::jsonb, '["At least 4 screens, genuinely connected as a flow, not isolated screens", "Annotations show real reasoning, not just labels", "Flow is logical for the stated user goal", "Low-fidelity is appropriate \u2014 no premature visual polish"]'::jsonb, 1),
('uiux', 1, 'Design System Basics', 'Build a component/design system (colors, type, spacing, buttons, inputs).', 'easy', '["Define a color palette with clear usage (primary, secondary, semantic colors)", "Define a type scale (headings, body, captions) with sizes", "Build at least 5 reusable components (buttons, inputs, cards, etc.) with variants", "Document spacing rules used consistently across components"]'::jsonb, '["Figma component/variant features"]'::jsonb, '["Components actually use the defined palette and type scale consistently", "At least 5 components with meaningful variants (not just 1 button style)", "Spacing is systematic (e.g. a scale), not arbitrary per component", "System is usable \u2014 another designer could build a screen from it"]'::jsonb, 2),
('uiux', 2, 'Hi-Fi Prototype', 'Turn wireframes into a high-fidelity prototype in Figma.', 'medium', '["Builds on the Week 1 wireframe flow with full visual design applied", "Uses the design system components from Week 1 Task 2", "Prototype is clickable/interactive between screens in Figma", "Includes at least one micro-interaction or transition"]'::jsonb, '["Figma prototyping mode"]'::jsonb, '["Prototype is genuinely clickable end-to-end, not static images", "Design system components are actually reused, not redrawn", "Visual design is polished and consistent", "At least one interactive/transition detail is present"]'::jsonb, 1),
('uiux', 2, 'Usability Test', 'Run a usability test on your prototype and write up findings.', 'medium', '["Test the prototype with at least 3 real people (not yourself)", "Give them a real task to complete, observe without guiding them", "Document what worked, what confused them, and specific quotes/observations", "Propose at least 2 concrete design changes based on findings"]'::jsonb, '["Any 3 willing friends/classmates/family as test participants"]'::jsonb, '["At least 3 real test sessions genuinely conducted, not simulated", "Findings are specific and evidence-based, not generic", "Proposed changes clearly connect to an observed problem", "Write-up is clear enough for someone else to act on"]'::jsonb, 2),
('uiux', 3, 'Redesign & Justify', 'Redesign an existing app/page and justify every change you made.', 'hard', '["Choose a real existing app/page with genuine usability issues", "Redesign at least 2 screens", "Every significant change is justified with a specific reason (not just taste)", "Before/after comparison is presented side by side"]'::jsonb, '["Any real app you use and have opinions about"]'::jsonb, '["Redesign addresses real, identifiable problems in the original", "Every major change has a stated rationale", "Before/after is genuinely easy to compare", "Redesign is a real improvement, not change for its own sake"]'::jsonb, 1),
('uiux', 3, 'Responsive Flow', 'Design a full responsive flow (mobile and desktop) for a product.', 'hard', '["Same user flow designed for both mobile and desktop, at least 4 screens each", "Layout genuinely adapts (not just scaled), respecting each form factor''s conventions", "Consistent design system/components used across both", "Key interactions (nav, primary actions) work sensibly on both"]'::jsonb, '["Figma with mobile and desktop frames"]'::jsonb, '["Mobile and desktop are truly distinct layouts, not one just shrunk down", "Design system consistency is maintained across both", "Navigation pattern is appropriate to each form factor", "Flow logic (what happens after each action) is consistent across both"]'::jsonb, 2),
('uiux', 4, 'Capstone: Brief to Handoff', 'Take a product brief from research through wireframe, hi-fi prototype, to a handoff-ready design file.', 'hard', '["Starts from a written product brief with a clear user goal", "Shows the full process: research notes, wireframes, hi-fi prototype", "Final file is handoff-ready: labeled layers, spacing/color specs, component states", "Includes a short case-study write-up explaining decisions end-to-end"]'::jsonb, '["Figma Dev Mode or clear manual annotations for handoff"]'::jsonb, '["Full process is documented, not just the final screens", "Handoff file is genuinely usable by a developer without guesswork", "Case study clearly explains the reasoning at each stage", "Final design coherently solves the original brief''s goal"]'::jsonb, 1),
('cybersecurity', 1, 'Recon & Scanning Basics', 'Set up and use core security tools (basic recon, scanning) on a sandboxed target.', 'easy', '["Use a legal, sandboxed/intentionally-vulnerable target only (never a real external system without permission)", "Perform basic reconnaissance (open ports, running services)", "Document findings clearly with tool output included", "Explain what each finding means and why it matters"]'::jsonb, '["OWASP Juice Shop or DVWA as a legal practice target", "nmap for basic scanning"]'::jsonb, '["Only a sandboxed/authorized target was used \u2014 this is checked, not assumed", "Findings are documented with actual tool output, not just claims", "Explanations show real understanding of each finding", "No illegal/unauthorized scanning is present in the submission"]'::jsonb, 1),
('cybersecurity', 1, 'OWASP Top 10 Review', 'Identify and document common vulnerabilities (OWASP Top 10) in a sample app.', 'easy', '["Use a legal intentionally-vulnerable app (e.g. Juice Shop, DVWA)", "Identify at least 3 distinct OWASP Top 10 vulnerabilities present", "For each, explain the risk and how an attacker could exploit it", "Suggest a concrete fix for each"]'::jsonb, '["OWASP Top 10 official list", "OWASP Juice Shop / DVWA"]'::jsonb, '["At least 3 genuinely distinct vulnerabilities identified, not variations of one", "Risk explanation is accurate and specific to the app", "Suggested fixes are technically sound", "Only legal practice targets were used"]'::jsonb, 2),
('cybersecurity', 2, 'Vulnerability Scan & Fix Report', 'Perform a basic vulnerability scan and write a fix report.', 'medium', '["Run an automated scan against a legal, sandboxed target", "Triage results \u2014 not everything a scanner flags is real/urgent", "Report prioritizes findings by actual severity/impact", "At least one finding is manually verified, not just trusted from the scanner"]'::jsonb, '["OWASP ZAP for automated scanning"]'::jsonb, '["Scan output is included as evidence", "Findings are correctly prioritized, not just listed in scanner order", "At least one manual verification is shown, demonstrating real understanding", "Report is professional and readable by a non-technical stakeholder"]'::jsonb, 1),
('cybersecurity', 2, 'Harden Authentication', 'Harden an app''s authentication — rate limiting, password policy, session handling.', 'medium', '["Start from an app with weak auth (yours from an earlier week, or a provided sample)", "Add rate limiting on login attempts", "Enforce a real password policy (length/complexity)", "Fix at least one session-handling issue (e.g. session fixation, missing expiry)"]'::jsonb, '["OWASP Authentication Cheat Sheet"]'::jsonb, '["Rate limiting is demonstrated actually blocking repeated attempts", "Password policy is enforced server-side, not just in the UI", "Session fix is real and verified, not just theoretical", "App still functions correctly for legitimate users after hardening"]'::jsonb, 2),
('cybersecurity', 3, 'Monitoring & Alerting', 'Set up basic monitoring/alerting for suspicious activity.', 'hard', '["Define what ''suspicious'' means for your target app (e.g. repeated failed logins, unusual access patterns)", "Implement logging that captures the relevant events", "Set up an actual alert (email/Slack) when the threshold is crossed", "Demonstrate the alert firing on a simulated suspicious event"]'::jsonb, '["Simple log-based alerting, or a tool like Fail2ban for a demo"]'::jsonb, '["Alert is demonstrated actually firing on a real simulated event", "Definition of ''suspicious'' is reasonable and justified", "Logging captures enough detail to investigate an incident", "No excessive false-positive alerts on normal usage"]'::jsonb, 1),
('cybersecurity', 3, 'API Security Review', 'Perform a security review of an API and document findings.', 'hard', '["Review a real API (yours from an earlier week, or a provided sample)", "Check for at least 4 categories of issues (auth, input validation, rate limiting, data exposure)", "Document findings with severity and evidence for each", "Provide specific remediation steps, not generic advice"]'::jsonb, '["OWASP API Security Top 10"]'::jsonb, '["At least 4 genuinely distinct issue categories reviewed", "Each finding has real evidence (a request/response, not just a claim)", "Severity ratings are reasonable and justified", "Remediation steps are specific and actionable"]'::jsonb, 2),
('cybersecurity', 4, 'Capstone: Full Security Audit', 'Full security audit of a sample application — find, document, and fix real vulnerabilities, with a professional report.', 'hard', '["Combines recon, vulnerability scanning, and manual review on one target application", "At least 5 findings across different categories, each with evidence", "At least 2 findings are actually fixed, with before/after proof", "Final report is professional: executive summary, findings, remediation, suitable to hand to a client"]'::jsonb, '["Everything from Weeks 1-3 as your toolkit"]'::jsonb, '["At least 5 findings with real evidence, not padded with duplicates", "At least 2 fixes are demonstrated working, not just described", "Report is genuinely professional and well-organized", "Only legal, authorized/sandboxed targets were used throughout"]'::jsonb, 1),
('devops', 1, 'Containerize an App', 'Containerize an app with Docker.', 'easy', '["Write a Dockerfile for a real app (yours from an earlier track, or provided)", "Image builds successfully and the app runs correctly in the container", "Use a reasonably small base image, not bloated unnecessarily", "Include a docker-compose file if the app needs a database/other services"]'::jsonb, '["Docker docs, official language-specific base images"]'::jsonb, '["docker build and docker run both work without errors", "App functions correctly inside the container, tested directly", "Image size is reasonable for the app type", "docker-compose (if used) brings up all services correctly together"]'::jsonb, 1),
('devops', 1, 'CI Pipeline', 'Set up a CI pipeline (lint/test/build on push).', 'easy', '["Pipeline triggers automatically on every push/PR", "Runs lint, tests, and a build step, in that order", "Pipeline fails visibly (red X) when any step fails", "README documents what the pipeline checks"]'::jsonb, '["GitHub Actions"]'::jsonb, '["A genuine failing commit correctly fails the pipeline, demonstrated", "A genuine passing commit correctly passes", "All 3 steps (lint/test/build) are present and real, not stubbed", "Pipeline status is visible on the repo"]'::jsonb, 2),
('devops', 2, 'CD to Auto-Deploy', 'Set up CD to auto-deploy on merge to main.', 'medium', '["Builds on the CI pipeline from Week 1", "Merging to main triggers an automatic deployment", "Deployment only happens if CI checks pass first", "Deployed app is verified reachable after each deploy"]'::jsonb, '["Vercel/Railway/Render''s Git integration, or a custom GitHub Actions deploy step"]'::jsonb, '["A real merge to main is demonstrated triggering deployment", "A failing CI check correctly blocks deployment", "Live app reflects the latest merged code after deploy", "Rollback path exists if a bad deploy goes out"]'::jsonb, 1),
('devops', 2, 'Monitoring & Logging', 'Set up monitoring/logging for a deployed app.', 'medium', '["Deployed app has centralized logging (not just scattered console output)", "At least one real metric tracked (uptime, response time, error rate)", "A dashboard or view where logs/metrics can actually be checked", "At least one alert configured for a real failure condition"]'::jsonb, '["Vercel/hosting provider''s built-in logs, or a tool like Better Stack/Sentry"]'::jsonb, '["Logs are genuinely centralized and searchable", "At least one real metric is tracked and visible", "Alert is demonstrated firing on a simulated failure", "Setup is documented well enough to hand off"]'::jsonb, 2),
('devops', 3, 'Infra as Code', 'Set up infrastructure as code for a simple service.', 'hard', '["Define infrastructure (even simple: a DB, a storage bucket, env config) in code, not manual dashboard clicks", "Infra can be recreated from the code alone, from scratch", "Changes go through the code, not manual edits in the provider''s dashboard", "Document the deploy/apply process clearly"]'::jsonb, '["Terraform, or the hosting provider''s own IaC tool"]'::jsonb, '["Infra genuinely can be torn down and recreated from code", "No manual dashboard changes bypass the code", "Apply/plan process is documented and repeatable", "Secrets aren''t hardcoded into the IaC files"]'::jsonb, 1),
('devops', 3, 'Zero-Downtime Deploys', 'Implement zero-downtime deploys and a rollback strategy.', 'hard', '["Deploys don''t cause visible downtime/errors for users during the release", "A clear rollback process exists and is documented", "Demonstrate a rollback actually working on a simulated bad deploy", "Health checks used to confirm a new version is healthy before fully cutting over"]'::jsonb, '["Blue-green or rolling deploy features of your hosting provider"]'::jsonb, '["Zero-downtime behavior is demonstrated, not just claimed", "Rollback is demonstrated actually working, not just described", "Health checks correctly catch an unhealthy deploy before full cutover", "Process is documented clearly enough to execute under pressure"]'::jsonb, 2),
('devops', 4, 'Capstone: Full CI/CD Pipeline', 'Take an app from zero to a fully automated CI/CD pipeline with monitoring, alerting, and rollback, documented end-to-end.', 'hard', '["Combines containerization, CI, CD, monitoring, and rollback into one pipeline", "A push to main results in a fully automated path to a monitored production deploy", "At least one alert and one rollback are demonstrated working on simulated failures", "Full documentation covers architecture, pipeline stages, and operating procedures"]'::jsonb, '["Everything from Weeks 1-3 as your building blocks"]'::jsonb, '["Full pipeline runs end-to-end from push to live deploy without manual steps", "Alert and rollback are both demonstrated working, not just described", "Documentation is complete enough to hand off to someone else", "No manual/undocumented steps are secretly required to make it work"]'::jsonb, 1);
insert into quizzes (domain, questions, passing_score) values
('frontend', '[{"question": "What does CSS stand for?", "options": ["Cascading Style Sheets", "Creative Style System", "Computer Styled Sections", "Colorful Style Sheets"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which HTML tag is used for the largest heading?", "options": ["<h6>", "<heading>", "<h1>", "<head>"], "correct_index": 2, "difficulty": "easy"}, {"question": "Which method adds an element to the end of a JS array?", "options": ["push()", "append()", "add()", "insert()"], "correct_index": 0, "difficulty": "easy"}, {"question": "What does the ''D'' in DOM stand for?", "options": ["Document", "Data", "Design", "Display"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which CSS property controls text size?", "options": ["font-size", "text-size", "font-style", "text-style"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is the correct HTML tag for inserting a line break?", "options": ["<break>", "<br>", "<lb>", "<newline>"], "correct_index": 1, "difficulty": "easy"}, {"question": "Which keyword declares a block-scoped variable in JS?", "options": ["var", "let", "global", "static"], "correct_index": 1, "difficulty": "easy"}, {"question": "What does JSX stand for?", "options": ["JavaScript XML", "Java Syntax Extension", "JSON XML", "JavaScript Extension"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which HTTP method is typically used to fetch data?", "options": ["GET", "SET", "FETCH", "PULL"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which array method creates a new array with results of calling a function on every element?", "options": ["forEach()", "map()", "filter()", "reduce()"], "correct_index": 1, "difficulty": "easy"}, {"question": "In React, what triggers a re-render of a functional component?", "options": ["Changing a state or prop value", "Refreshing the browser only", "Calling console.log", "Editing the CSS file"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the purpose of React''s useEffect hook?", "options": ["To perform side effects after render", "To create new components", "To style components", "To define props"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''CSS specificity'' determine?", "options": ["Which CSS rule applies when multiple rules match an element", "How fast CSS loads", "Which browser supports the rule", "The file size of CSS"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the CSS box model, in order from inside out?", "options": ["Content, padding, border, margin", "Margin, border, padding, content", "Content, margin, padding, border", "Border, content, padding, margin"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the main difference between ''let'' and ''const'' in JS?", "options": ["''const'' cannot be reassigned after declaration", "''let'' is function-scoped, ''const'' is block-scoped", "''const'' allows redeclaration", "There is no difference"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does the CSS Flexbox property ''justify-content'' control?", "options": ["Alignment of items along the main axis", "Alignment of items along the cross axis", "The order of flex items", "The wrapping of flex items"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is a ''closure'' in JavaScript?", "options": ["A function that retains access to its outer scope''s variables", "A way to close a browser tab", "A CSS layout technique", "A type of loop"], "correct_index": 0, "difficulty": "hard"}, {"question": "In React, what is the purpose of a ''key'' prop in a list?", "options": ["To help React identify which items changed, were added, or removed", "To style list items uniquely", "To set the list''s CSS class", "To define the list''s data type"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''event bubbling'' mean in the DOM?", "options": ["An event triggers on the target element and then propagates up to ancestors", "An event only triggers on the exact target element", "Events are queued and fire in random order", "An event cancels all other events"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the difference between ''=='' and ''==='' in JavaScript?", "options": ["''==='' checks both value and type; ''=='' only checks value with type coercion", "''=='' checks both value and type; ''==='' only checks value", "They behave identically", "''==='' is used only for strings"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''async/await'' do in JavaScript?", "options": ["Provides a cleaner syntax for working with Promises", "Makes code run in parallel threads", "Blocks the entire browser until complete", "Replaces the need for functions"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the Virtual DOM in React?", "options": ["An in-memory representation of the real DOM used to optimize updates", "A backup copy of the HTML file", "A browser plugin", "A CSS rendering engine"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''debouncing'' a function accomplish?", "options": ["Delays execution until after a pause in events, limiting how often it runs", "Runs the function twice for safety", "Removes bugs from the function", "Makes the function run faster"], "correct_index": 0, "difficulty": "hard"}, {"question": "Which CSS unit is relative to the root element''s font size?", "options": ["rem", "px", "em", "vh"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''CORS'' stand for and what does it control?", "options": ["Cross-Origin Resource Sharing \u2014 controls which origins can access a resource", "Client-Origin Resource Sync \u2014 controls caching", "Cross-Origin Rendering Style \u2014 controls page layout", "Central Object Resource Server \u2014 controls database access"], "correct_index": 0, "difficulty": "hard"}, {"question": "In React, what does ''lifting state up'' mean?", "options": ["Moving shared state to the closest common ancestor component", "Increasing a state variable''s value", "Moving CSS into a parent stylesheet", "Deleting unused state variables"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is ''semantic HTML''?", "options": ["HTML that uses tags conveying meaning about their content, like <article> or <nav>", "HTML with inline styles", "HTML validated by W3C only", "HTML written in uppercase"], "correct_index": 0, "difficulty": "hard"}, {"question": "What problem does ''localStorage'' solve compared to cookies?", "options": ["Stores larger amounts of data client-side without being sent on every HTTP request", "Automatically syncs across devices", "Encrypts data by default", "Expires after each session"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''tree shaking'' do in a modern JS bundler?", "options": ["Removes unused code from the final bundle", "Reorders CSS rules alphabetically", "Compresses images automatically", "Converts JSX to HTML"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the purpose of React''s Context API?", "options": ["To share data across components without manually passing props at every level", "To fetch data from a REST API", "To manage CSS themes only", "To replace all component state"], "correct_index": 0, "difficulty": "hard"}]'::jsonb, 70),
('backend', '[{"question": "What does API stand for?", "options": ["Application Programming Interface", "Applied Program Instruction", "Automated Process Integration", "Application Process Index"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which HTTP status code means ''Not Found''?", "options": ["200", "301", "404", "500"], "correct_index": 2, "difficulty": "easy"}, {"question": "What does CRUD stand for?", "options": ["Create, Read, Update, Delete", "Copy, Run, Undo, Debug", "Create, Run, Update, Deploy", "Connect, Read, Upload, Delete"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which of these is a NoSQL database?", "options": ["MongoDB", "MySQL", "PostgreSQL", "SQLite"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is the default port for HTTP?", "options": ["80", "443", "8080", "21"], "correct_index": 0, "difficulty": "easy"}, {"question": "What does REST stand for?", "options": ["Representational State Transfer", "Remote Execution State Transfer", "Rapid State Transmission", "Representational Style Transfer"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which HTTP method is used to update an existing resource entirely?", "options": ["PUT", "GET", "POST", "DELETE"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is middleware in the context of Express.js?", "options": ["A function that has access to the request/response cycle and can modify or end it", "A database connection pool", "A frontend rendering engine", "A type of HTTP status code"], "correct_index": 0, "difficulty": "easy"}, {"question": "What does JWT stand for?", "options": ["JSON Web Token", "Java Web Toolkit", "JavaScript Web Transfer", "JSON Website Type"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is the purpose of an environment variable in a backend app?", "options": ["To store configuration values outside the codebase, like API keys", "To style the frontend", "To define database tables", "To compile the code"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is the main risk of storing passwords in plain text?", "options": ["Anyone with database access can read every user''s password directly", "It uses more storage space", "It slows down login speed", "It breaks JSON formatting"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''idempotent'' mean for an HTTP method like PUT?", "options": ["Calling it multiple times has the same effect as calling it once", "It can only be called once ever", "It always returns a 200 status", "It requires authentication"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the purpose of database indexing?", "options": ["To speed up data retrieval at the cost of extra storage and slower writes", "To encrypt sensitive columns", "To automatically back up the database", "To enforce foreign key constraints"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is a race condition?", "options": ["A bug where the outcome depends on the unpredictable timing of concurrent operations", "A slow database query", "An error in CSS rendering", "A type of SQL injection"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''rate limiting'' protect an API from?", "options": ["Being overwhelmed by too many requests in a short time, intentional or not", "Data being stored in the wrong format", "CSS conflicts between routes", "Slow client-side rendering"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the difference between authentication and authorization?", "options": ["Authentication verifies identity; authorization determines what that identity can access", "They are the same concept", "Authorization happens before authentication always", "Authentication only applies to admins"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is a common purpose of a message queue (e.g. RabbitMQ, SQS)?", "options": ["Decoupling services and processing tasks asynchronously in the background", "Storing user session cookies", "Rendering server-side HTML", "Compressing images on upload"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is SQL injection?", "options": ["An attack that inserts malicious SQL through unsanitized user input", "A method of speeding up SQL queries", "A way to join two SQL tables", "A type of database backup"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''horizontal scaling'' mean?", "options": ["Adding more machines/instances to handle load", "Adding more CPU/RAM to a single machine", "Reducing the number of servers", "Compressing the database"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the purpose of a foreign key in a relational database?", "options": ["To enforce a link between rows in two tables and maintain referential integrity", "To encrypt a column", "To speed up full-text search", "To auto-generate primary keys"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the N+1 query problem?", "options": ["Making one query per related record instead of a single batched query, causing excessive DB calls", "Running exactly one extra query per request always", "A database that has one too many tables", "A type of SQL syntax error"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''statelessness'' mean in REST APIs?", "options": ["Each request contains all the information needed; the server stores no client session state between requests", "The server has no database", "The API returns no response body", "Requests never fail"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the purpose of hashing a password before storing it?", "options": ["So the original password can''t be recovered even if the database is breached", "To make passwords shorter", "To make login faster", "To allow case-insensitive comparison"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is a webhook?", "options": ["A user-defined HTTP callback triggered by an event in another system", "A type of firewall rule", "A CSS animation technique", "A database index type"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ACID stand for in database transactions?", "options": ["Atomicity, Consistency, Isolation, Durability", "Access, Control, Identity, Data", "Authentication, Caching, Indexing, Distribution", "Atomic, Cached, Indexed, Deployed"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the purpose of connection pooling in a database client?", "options": ["Reusing a limited set of open connections instead of opening a new one per request", "Encrypting all database traffic", "Automatically sharding the database", "Compressing query results"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does CORS actually restrict?", "options": ["Which origins a browser will allow to make requests to your API", "Which countries can access your server", "How many requests per second are allowed", "Which HTTP methods exist"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the difference between PUT and PATCH?", "options": ["PUT replaces the entire resource; PATCH applies a partial update", "They are identical in every way", "PATCH is only for images", "PUT cannot be used with JSON"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is a common mitigation for brute-force login attempts?", "options": ["Rate limiting and account lockout after repeated failures", "Storing passwords in plain text for faster checks", "Disabling HTTPS", "Removing all logging"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''least privilege'' mean in access control design?", "options": ["Granting a user or service only the permissions it needs to function, nothing more", "Giving all users admin access by default", "Removing all permissions checks for speed", "Only applying to the database admin"], "correct_index": 0, "difficulty": "hard"}]'::jsonb, 70),
('fullstack', '[{"question": "What does ''full-stack'' typically mean?", "options": ["Working across both frontend and backend of an application", "Only working on databases", "Only working on UI design", "Working exclusively with mobile apps"], "correct_index": 0, "difficulty": "easy"}, {"question": "Which of these is typically a frontend framework, not backend?", "options": ["React", "Express", "Django", "Flask"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is the purpose of an environment variable file like .env?", "options": ["To store config/secrets outside of source code", "To store compiled CSS", "To define HTML templates", "To store frontend images"], "correct_index": 0, "difficulty": "easy"}, {"question": "What does ''deployment'' mean?", "options": ["Making an application available for users to access, typically on a server", "Writing the first line of code", "Designing the database schema", "Testing code locally only"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is a common purpose of Git?", "options": ["Version control \u2014 tracking changes to code over time", "Styling web pages", "Sending emails", "Hosting databases"], "correct_index": 0, "difficulty": "easy"}, {"question": "What does ''client-server architecture'' describe?", "options": ["A model where clients request resources/services from a server", "A single-file application with no network calls", "A CSS layout system", "A database indexing strategy"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is JSON commonly used for in full-stack apps?", "options": ["Exchanging structured data between frontend and backend", "Styling components", "Compiling code", "Storing binary images directly"], "correct_index": 0, "difficulty": "easy"}, {"question": "What does ''CI/CD'' stand for?", "options": ["Continuous Integration / Continuous Deployment (or Delivery)", "Code Inspection / Code Distribution", "Client Integration / Client Deployment", "Continuous Iteration / Continuous Design"], "correct_index": 0, "difficulty": "easy"}, {"question": "What is the role of a database in a full-stack app?", "options": ["Persisting data so it''s available across sessions and requests", "Rendering the UI", "Compiling JavaScript", "Sending HTTP requests"], "correct_index": 0, "difficulty": "easy"}, {"question": "What does ''authentication token'' typically allow a client to do?", "options": ["Prove its identity on subsequent requests without re-sending credentials", "Style the page", "Compress images", "Skip the database entirely"], "correct_index": 0, "difficulty": "easy"}, {"question": "In a typical full-stack app, what problem does state management (e.g. Redux, Zustand) solve?", "options": ["Keeping shared UI state consistent and predictable across components", "Storing files on the server", "Sending emails to users", "Encrypting API keys"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is server-side rendering (SSR)?", "options": ["Rendering HTML on the server before sending it to the browser, rather than purely in client JS", "Rendering only on mobile devices", "A CSS animation library", "A way to store data in cookies"], "correct_index": 0, "difficulty": "hard"}, {"question": "Why use an ORM (Object-Relational Mapper)?", "options": ["To interact with a database using code objects instead of raw SQL", "To style database tables", "To replace HTTP entirely", "To compress database backups"], "correct_index": 0, "difficulty": "hard"}, {"question": "What is the purpose of database migrations?", "options": ["Versioning and applying incremental changes to a database schema over time", "Migrating a database to a different cloud provider only", "Compressing old records", "Renaming CSS classes"], "correct_index": 0, "difficulty": "hard"}, {"question": "What does ''optimistic UI update'' mean?", "options": ["Updating the UI immediately assuming a request will succeed, then reconciling if it fails", "Always showing a loadi